#!/usr/bin/env pwsh
# Generated by Claude Opus 5.5 (claude.ai/code) · 2026-11-17

<#
.SYNOPSIS
  Recipe: hot backup of a Linux host's own configuration (files + facts).
.DESCRIPTION
  A backup recipe. The engine passes a RecipeContext as -Recipe; this script
  registers one step, 'dump', which runs without stopping anything:

    <service>_files.tar   standard host config: /etc, user crontabs,
                          /usr/local/etc, /root, plus HCL_EXTRA_DIRS.
                          Secrets are ALWAYS left out (a rebuilt host gets new ones).
    facts/<name>.txt      output of commands describing the machine (packages,
                          disks, network, firewall, enabled units, docker, and the
                          tools in /usr/local/{bin,sbin}: listed with size, date and
                          sha256, not archived; they are software, reinstalled on a
                          rebuild). Not restorable: a checklist for rebuilding by hand.

  Parameters (service config env):
    HCL_EXTRA_DIRS          extra absolute dirs to archive, ';'-separated (optional)
    HCL_EXCLUDES            extra excludes, ';'-separated (optional). An entry
                            starting with '/' is an absolute path (anchored); any
                            other entry is a name pattern matched anywhere.
    HCL_FILES_ARCHIVE_NAME  files tar name          (default: '<service>_files.tar')
    HCL_ROOT                root the paths are read under (default: '/'); for a
                            mounted system image, or tests
  Every path is stored relative to the root (etc/fstab, root/.bashrc, ...).
  Facts describe the running system; only the usr-local listing follows HCL_ROOT.

  Missing default dirs are skipped (distros differ); a missing HCL_EXTRA_DIRS entry
  is a validation problem. A fact command that is not installed is skipped and
  listed in facts/_skipped.txt; one that fails or times out keeps its output plus
  the exit code and stderr in its file, and gives one warning (not a failure).
  tar exit 1 ("file changed as we read it") is a warning too.

  Not caught: secrets written inline in ordinary config files (an fstab mount with
  user:password, cron lines, netplan Wi-Fi keys). Exclude them with HCL_EXCLUDES or
  move them to separate credential files.
#>

param($Recipe)

if ($null -eq $Recipe) {
    Write-Host 'This is a sequencer recipe; it is loaded by the engine, not run directly.'
    return
}

# Shared by the step and the validate block (functions defined here would be out of
# scope when the engine later invokes a step). Returns the tar plan: Root, the
# member list (relative to Root), anchored and unanchored excludes, missing extras.
$Recipe.State['HclPlan'] = {
    param($ctx)
    $split = { param($s) @($s.Split(';', [System.StringSplitOptions]::RemoveEmptyEntries) | ForEach-Object { $_.Trim() } | Where-Object { $_ }) }
    $rel = { param($p) ($p -replace '\\', '/').Trim('/') }
    $root = $ctx.EnvValue('HCL_ROOT', '/')

    $defaults = @('etc', 'var/spool/cron/crontabs', 'usr/local/etc', 'root')
    $members = @($defaults | Where-Object { Test-Path -LiteralPath (Join-Path $root $_) })
    $missingExtra = @()
    foreach ($d in (& $split $ctx.EnvValue('HCL_EXTRA_DIRS', ''))) {
        $m = & $rel $d
        if (-not $m) { continue }
        if (Test-Path -LiteralPath (Join-Path $root $m)) {
            if ($members -notcontains $m) { $members += $m }
        }
        else { $missingExtra += $d }
    }

    # secrets: fixed paths (anchored; tar wildcards allowed)
    $anchored = @(
        'etc/shadow*', 'etc/gshadow*', 'etc/security/opasswd',
        'etc/ssh/ssh_host_*_key', 'etc/ssl/private', 'etc/pki/tls/private', 'etc/letsencrypt',
        'etc/wireguard', 'etc/openvpn', 'etc/ipsec.secrets', 'etc/swanctl/private',
        'etc/NetworkManager/system-connections', 'etc/wpa_supplicant',
        'etc/krb5.keytab', 'etc/ldap.secret', 'etc/samba/smbpasswd', 'etc/sssd',
        'etc/postfix/sasl_passwd*', 'etc/msmtprc', 'etc/ssmtp', 'etc/ddclient.conf',
        'etc/mysql/debian.cnf', 'etc/davfs2/secrets', 'etc/apt/auth.conf*', 'etc/ceph/*.keyring',
        'etc/credstore*', 'etc/backup-sequencer/secrets',
        'root/.cache'
    )
    # the sequencer's own restic password, wherever it is configured
    $pw = $ctx.EnvValue('RESTIC_PASSWORD_FILE', '')
    if ($pw.StartsWith('/')) { $anchored += (& $rel $pw) }

    # secrets: name patterns, matched anywhere in the archived trees
    $unanchored = @(
        '*.key', '*.p12', '*.pfx', '*.keytab', '*.keyring',
        'id_rsa', 'id_dsa', 'id_ecdsa', 'id_ed25519', 'id_ecdsa_sk', 'id_ed25519_sk',
        '.netrc', '.pgpass', '.my.cnf', '.git-credentials', '.smbcredentials', '*credentials*',
        '.docker/config.json', '.config/rclone', '.aws', '.azure', '.kube', '.gnupg', '.local/share/keyrings',
        '.*_history', '.lesshst'
    )

    foreach ($e in (& $split $ctx.EnvValue('HCL_EXCLUDES', ''))) {
        if ($e.StartsWith('/')) { $anchored += (& $rel $e) } else { $unanchored += $e }
    }

    return @{ Root = $root; Members = $members; Anchored = $anchored; Unanchored = $unanchored; MissingExtra = $missingExtra }
}

# Facts: Name (file name) + either Exe/Args (a command) or Script (param($ctx),
# returns lines). Tests may replace this list.
$Recipe.State['HclFacts'] = @(
    @{ Name = 'uname'; Exe = 'uname'; Args = @('-a') }
    @{ Name = 'hostnamectl'; Exe = 'hostnamectl'; Args = @() }
    @{ Name = 'dpkg-selections'; Exe = 'dpkg'; Args = @('--get-selections') }
    @{ Name = 'apt-manual'; Exe = 'apt-mark'; Args = @('showmanual') }
    @{ Name = 'apt-policy'; Exe = 'apt-cache'; Args = @('policy') }
    @{ Name = 'lsblk'; Exe = 'lsblk'; Args = @('-O') }
    @{ Name = 'blkid'; Exe = 'blkid'; Args = @() }
    @{ Name = 'fdisk'; Exe = 'fdisk'; Args = @('-l') }
    @{ Name = 'df'; Exe = 'df'; Args = @('-hT') }
    @{ Name = 'findmnt'; Exe = 'findmnt'; Args = @() }
    @{ Name = 'mdadm'; Exe = 'mdadm'; Args = @('--detail', '--scan', '--verbose') }
    @{ Name = 'zpool-status'; Exe = 'zpool'; Args = @('status') }
    @{ Name = 'zfs-list'; Exe = 'zfs'; Args = @('list') }
    @{ Name = 'ip-addr'; Exe = 'ip'; Args = @('addr') }
    @{ Name = 'ip-route'; Exe = 'ip'; Args = @('route') }
    @{ Name = 'iptables'; Exe = 'iptables-save'; Args = @() }
    @{ Name = 'nft'; Exe = 'nft'; Args = @('list', 'ruleset') }
    @{ Name = 'systemd-enabled'; Exe = 'systemctl'; Args = @('list-unit-files', '--state=enabled', '--no-pager') }
    @{ Name = 'systemd-timers'; Exe = 'systemctl'; Args = @('list-timers', '--all', '--no-pager') }
    @{ Name = 'docker-version'; Exe = 'docker'; Args = @('version') }
    @{ Name = 'docker-images'; Exe = 'docker'; Args = @('images') }
    @{ Name = 'docker-networks'; Exe = 'docker'; Args = @('network', 'ls') }
    @{ Name = 'docker-compose-ls'; Exe = 'docker'; Args = @('compose', 'ls', '-a') }
    @{ Name = 'usr-local'; Script = {
            # locally installed tools: what to reinstall on a rebuild (not archived)
            param($ctx)
            $root = $ctx.EnvValue('HCL_ROOT', '/')
            'type  size  modified  sha256  path [-> target]'
            foreach ($d in 'usr/local/bin', 'usr/local/sbin') {
                $full = Join-Path $root $d
                if (-not (Test-Path -LiteralPath $full -PathType Container)) { continue }
                foreach ($i in (Get-ChildItem -LiteralPath $full -Force | Sort-Object Name)) {
                    $path = "/$d/$($i.Name)"
                    $mod = $i.LastWriteTimeUtc.ToString('yyyy-MM-dd', [System.Globalization.CultureInfo]::InvariantCulture)
                    if ($i.LinkType) { "link  -  $mod  -  $path -> $($i.Target)" }
                    elseif ($i.PSIsContainer) { "dir  -  $mod  -  $path" }
                    else {
                        $hash = try { (Get-FileHash -LiteralPath $i.FullName -Algorithm SHA256).Hash.ToLowerInvariant() } catch { 'unreadable' }
                        "file  $($i.Length)  $mod  $hash  $path"
                    }
                }
            }
        }
    }
)
$Recipe.State['HclFactTimeoutSec'] = 60

$Recipe.AddStep('dump', {
    param($ctx)
    New-Item -ItemType Directory -Force -Path $ctx.OutDir | Out-Null
    $plan = & $ctx.State['HclPlan'] $ctx
    if ($plan.MissingExtra.Count -gt 0) { throw "HCL_EXTRA_DIRS missing: $($plan.MissingExtra -join ', ')" }
    if ($plan.Members.Count -eq 0) { throw "nothing to archive under $($plan.Root)" }

    # --- files tar: GNU tar applies --anchored / --no-anchored to the excludes after it ---
    $name = $ctx.EnvValue('HCL_FILES_ARCHIVE_NAME', "$($ctx.Service)_files.tar")
    $tarArgs = @('-C', $plan.Root, '--anchored')
    foreach ($e in $plan.Anchored) { $tarArgs += "--exclude=$e" }
    $tarArgs += '--no-anchored'
    foreach ($e in $plan.Unanchored) { $tarArgs += "--exclude=$e" }
    $tarArgs += @('-cf', (Join-Path $ctx.OutDir $name))
    $tarArgs += $plan.Members
    & tar @tarArgs
    if ($LASTEXITCODE -eq 1) {
        Write-Warning "$($ctx.Service) dump: some files changed while being read (expected for a live copy)"
    }
    elseif ($LASTEXITCODE -ne 0) {
        throw "tar of host config failed (exit $LASTEXITCODE)"
    }

    # --- facts: one file per command; never fails the step ---
    $factsDir = Join-Path $ctx.OutDir 'facts'
    New-Item -ItemType Directory -Force -Path $factsDir | Out-Null
    $timeoutMs = [int]$ctx.State['HclFactTimeoutSec'] * 1000
    $skipped = @()
    $failed = @()
    foreach ($f in $ctx.State['HclFacts']) {
        if ($f.ContainsKey('Script')) {
            try { & $f.Script $ctx | Set-Content -LiteralPath (Join-Path $factsDir "$($f.Name).txt") }
            catch {
                $failed += $f.Name
                Set-Content -LiteralPath (Join-Path $factsDir "$($f.Name).txt") -Value "--- failed: $($_.Exception.Message) ---"
            }
            continue
        }
        $cmd = Get-Command $f.Exe -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
        if (-not $cmd) { $skipped += "$($f.Name): $($f.Exe) not installed"; continue }
        $outFile = Join-Path $factsDir "$($f.Name).txt"
        $errFile = Join-Path $factsDir "$($f.Name).stderr"
        $spArgs = @{ FilePath = $cmd.Source; RedirectStandardOutput = $outFile; RedirectStandardError = $errFile; NoNewWindow = $true; PassThru = $true }
        if ($f.Args.Count -gt 0) { $spArgs.ArgumentList = $f.Args }
        $status = $null
        try {
            $p = Start-Process @spArgs
            $null = $p.Handle   # keep the handle so ExitCode is readable after exit
            if ($p.WaitForExit($timeoutMs)) {
                $p.WaitForExit()   # flush redirected output
                if ($p.ExitCode -ne 0) { $status = "exit $($p.ExitCode)" }
            }
            else {
                try { $p.Kill($true) } catch { }
                $status = "timed out after $($ctx.State['HclFactTimeoutSec'])s"
            }
        }
        catch { $status = "could not start: $($_.Exception.Message)" }
        if ($status) {
            $failed += $f.Name
            $err = ''
            if (Test-Path -LiteralPath $errFile) { $err = Get-Content -LiteralPath $errFile -Raw }
            Add-Content -LiteralPath $outFile -Value "`n--- $($f.Exe) $($f.Args -join ' '): $status ---`n$err"
        }
        Remove-Item -LiteralPath $errFile -Force -ErrorAction SilentlyContinue
    }
    if ($skipped.Count -gt 0) { Set-Content -LiteralPath (Join-Path $factsDir '_skipped.txt') -Value $skipped }
    if ($failed.Count -gt 0) {
        Write-Warning "$($ctx.Service) facts: $($failed.Count) command(s) failed: $($failed -join ', ') (details in facts/<name>.txt)"
    }
})

# preflight: Linux, tar, the root, and every HCL_EXTRA_DIRS entry
$Recipe.SetValidate({
    param($ctx)
    $problems = @()
    if (-not $IsLinux) { $problems += 'host-config-linux runs on Linux only' }
    if (-not (Get-Command tar -CommandType Application -ErrorAction SilentlyContinue)) { $problems += 'tar not found' }
    $root = $ctx.EnvValue('HCL_ROOT', '/')
    if (-not (Test-Path -LiteralPath $root -PathType Container)) {
        $problems += "HCL_ROOT missing: $root"
        return $problems
    }
    $plan = & $ctx.State['HclPlan'] $ctx
    foreach ($d in $plan.MissingExtra) { $problems += "HCL_EXTRA_DIRS entry missing: $d" }
    return $problems
})
